import hashlib
import random
import struct

KEYS = ['470FC614', '4A0FC614', '4B9FC614', '4C8FC614', '4D7FC614']

def task_func(hex_keys=KEYS, seed=42):
    if not hex_keys:
        raise ValueError("hex_keys must contain at least one hexadecimal string")

    parsed_keys = []
    for key in hex_keys:
        if not isinstance(key, str) or len(key) != 8:
            raise ValueError("All keys must be valid 8-character hexadecimal strings")
        try:
            parsed_keys.append(bytes.fromhex(key))
        except ValueError as exc:
            raise ValueError("All keys must be valid 8-character hexadecimal strings") from exc

    rng = random.Random(seed)
    selected = rng.choice(parsed_keys)

    float_value = struct.unpack("!f", selected)[0]
    return hashlib.md5(str(float_value).encode("utf-8")).hexdigest()

